CREATE TYPE "user_kind" AS ENUM (
  'admin',
  'guest'
);

CREATE TABLE "users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "score" decimal(5,2),
  "active" bool,
  "created" timestamp,
  "kind" user_kind
);

-- Defer constraint checking for INSERT
BEGIN;
SET CONSTRAINTS ALL DEFERRED;

INSERT INTO "users" ("id", "name", "score", "active", "created", "kind")
VALUES
  (1, 'Alice', 9.5, TRUE, '2024-01-02T03:04:05', 'undefined'),
  (2, 'Bob', -125, FALSE, NULL, 'guest'),
  (3, now(), 0, TRUE, '2024-01-02', 'undefined');

SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;